package gg.eternal.core.ui;
import gg.eternal.core.config.CoreConfig; import net.minecraft.client.gui.GuiGraphics; import net.minecraft.client.gui.screens.Screen; import net.minecraft.network.chat.Component;
public class ClickGuiScreen extends Screen { public ClickGuiScreen(){super(Component.literal("Eternal Client"));}
  @Override public void render(GuiGraphics g,int mx,int my,float dt){renderBackground(g,mx,my,dt);int w=420,x=(width-w)/2,y=(height-280)/2;g.fill(x,y,x+w,y+280,0xEE0A0A0C);g.fill(x,y,x+4,y+280,0xFFE01414);g.drawString(font,"ETERNAL",x+18,y+15,0xFFFF4141,true);g.drawString(font,"MODULES",x+18,y+35,0xFF77777F,false);int yy=y+58;for(String n:CoreConfig.INSTANCE.enabled.keySet()){boolean on=CoreConfig.INSTANCE.on(n);g.fill(x+16,yy,x+w-16,yy+22,on?0x332A0909:0x221F2023);g.drawString(font,n,x+26,yy+7,on?0xFFFFFFFF:0xFF77777F,false);g.drawString(font,on?"ON":"OFF",x+w-55,yy+7,on?0xFFFF5353:0xFF55555C,false);yy+=24;}super.render(g,mx,my,dt);}
  @Override public boolean mouseClicked(double mx,double my,int b){int x=(width-420)/2,y=(height-280)/2+58,idx=(int)((my-y)/24);if(mx>=x+16&&mx<=x+404&&idx>=0&&idx<CoreConfig.INSTANCE.enabled.size()){String name=CoreConfig.INSTANCE.enabled.keySet().toArray(String[]::new)[idx];CoreConfig.INSTANCE.toggle(name);return true;}return super.mouseClicked(mx,my,b);} @Override public boolean isPauseScreen(){return false;}
}
